// Pathtracing 
//-------------------------------

// Create Tangent Space Basis From Normal
void TangentBasis(vec3 normal, inout vec3 tangent, inout vec3 binormal){
    vec3 up = vec3(0,1,0);
    if(abs(normal.y) > 0.99) up = vec3(0,0,-1);

    binormal = normalize(cross(normal,up));
    tangent = cross(binormal,normal);
}


// Lambert BRDF
// Importance Sampling For Lambert BRDF
vec3 CosineSampling(vec2 xi){
    float theta = acos(1.0 - 2.0f * xi.x) * 0.5;
    float phi = 2.0 * PI * xi.y;
    return vec3(sin(theta) * cos(phi),cos(theta),sin(theta) * sin(phi));
}

vec3 EvaluateLambertBRDF(vec3 color){
    return color / PI;
}

// Sample Incident Direction and Evaluate BRDF
// Input
// wo : Outgoing Direction
// color : Surface Color
// xi : 2 Random Number

// Output 
// wi : Incident Direction
// pdf : Probability Density Function
// return : Lambert BRDF
vec3 SampleLambertBRDF(vec3 wo,vec3 color, vec2 xi, inout vec3 wi, inout float pdf){
    wi = CosineSampling(xi);
    pdf = wi.y / PI;
    return EvaluateLambertBRDF(color);
}

// Convert World Coordinate To Local Coordinate : lx, ly, lz
vec3 WorldToLocal(vec3 v,vec3 lx, vec3 ly,vec3 lz){
    return vec3(dot(v, lx),dot(v,ly),dot(v,lz));
}

// Convert Local Coodinate To World Coordinate
vec3 LocalToWorld(vec3 v, vec3 lx, vec3 ly, vec3 lz)
{
    return vec3(dot(v ,vec3(lx.x,ly.x,lz.x)),dot(v ,vec3(lx.y,ly.y,lz.y)),dot(v ,vec3(lx.z,ly.z,lz.z)));
}

vec3 Pathtrace(Ray firstRay){
    Ray ray = firstRay;

    vec3 LTE = vec3(0.0); // Radiance of Path
    vec3 throughput = vec3(1.0); // Attenuation of Path

    float rp = 1.0; // Probability for Rossian Roulette

    for(int i = 0; i < 5; i++){

        // Rossian Roullet
        // Probablitity Is Arbitrary [0,1]
        // Practically, Use Maximum of Thoughput. (if throughput is low, the path is low contribution, so not use the path)
        rp = clamp(max(max(throughput.x,throughput.y),throughput.z),0.0,1.0);
        if(rp < rnd1()) break;
        throughput /= rp; // Divide Probablity


        IntersectionInfo info;
        if(!Intersect(ray, info)){
            // No hit
            vec3 skyEmission = vec3(0.0);
            LTE = skyEmission * throughput;
            break;

        }

        if(length(info.emission) > 0.01){
           // Light Hit
           LTE = info.emission * throughput;
           break;
        }


        // Create Tangent Space Bisis
        vec3 normal = info.normal;
        vec3 tangent,binormal;
        TangentBasis(normal,tangent,binormal);

        // Outgoing Direction wo in Tangent Space
        vec3 wo = -ray.direction;
        vec3 local_wo = WorldToLocal(wo,tangent,normal,binormal);

        // Sample Incident Direction(Tangent Sapce) wi, pdf and Evaluate BSDF
        float pdf;
        vec3 local_wi;
        vec3 bsdf = SampleLambertBRDF(local_wo,info.color,rnd2(),local_wi,pdf);

        // Incident Direction in World Space
        vec3 wi = LocalToWorld(local_wi,tangent,normal,binormal);

        // Calculate Attenuation Rate Per One Bounce
        float cosine = dot(info.normal,wi);
        throughput *= bsdf * cosine / pdf; 

        // Next Ray
        ray.direction = wi;
        ray.origin = info.position + 0.02 * ray.direction; 

    }
    return LTE;
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    SetSeed(ivec2(fragCoord),iFrame);

    vec2 uv = (fragCoord * 2.0 + rnd2() - iResolution.xy) /iResolution.y;
    vec2 texuv = fragCoord / iResolution.xy;

    // Camera Ray 
    Ray ray;
    ray.origin = vec3(0,0,-4);
    ray.direction = normalize(vec3(uv,3));

    vec3 col;
    col = Pathtrace(ray);

    // Prefreme Resolution Check
    bool resize = texelFetch(iChannel0,ivec2(0),0).x != iResolution.x;

    // Accumulation
    vec4 accumCol = texture(iChannel0,texuv);
    if(resize) accumCol = vec4(col,1.0);
    else accumCol += vec4(col,1.0);

    // Store last resolution
    if(ivec2(fragCoord)==ivec2(0)) {
        accumCol = iResolution.xyxy;
    }

    fragColor = accumCol;
}
